/*
 * A243541  Numbers n such that the list of divisors of n contains 8 distinct
 *          digits (in base 10).
 * https://oeis.org/A243541
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   sequence generated by brute‑force search. a(n) is the n‑th
 *            positive integer whose set of divisors contains exactly eight
 *            distinct decimal digits
 * Range:     u8 n <= 19, u16 n <= 9893, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>
#include <stddef.h>

/* ---------- small prime table and helpers ---------- */
static uint64_t *primes = NULL;
static size_t primes_cnt = 0, primes_cap = 0;
static uint64_t last_checked = 1;

/* Add primes up to (and including) limit. No sqrt, no math.h. */
static void ensure_primes_up_to(uint64_t limit) {
    if (limit <= last_checked) return;
    for (uint64_t cand = last_checked + 1; cand <= limit; ++cand) {
        bool is_p = true;
        for (size_t i = 0; i < primes_cnt; ++i) {
            uint64_t p = primes[i];
            if (p > cand / p) break;        /* p*p > cand */
            if (cand % p == 0) {             /* composite */
                is_p = false;
                break;
            }
        }
        if (is_p) {
            if (primes_cnt == primes_cap) {
                primes_cap = primes_cap ? primes_cap * 2 : 16;
                primes = (uint64_t *)realloc(primes,
                                              primes_cap * sizeof(uint64_t));
            }
            primes[primes_cnt++] = cand;
        }
    }
    last_checked = limit;
}

/* ---------- factorisation into primes ---------- */
static void factor_uint64(uint64_t n, uint64_t *p, int *e, size_t *cnt) {
    *cnt = 0;
    uint64_t temp = n;
    /* Ensure we have enough primes for trial division up to sqrt(temp) */
    uint64_t lim = 0;
    for (uint64_t k = 2; k * k <= temp; ++k) { } /* pseudo loop to silence warning */
    /* Actually we can use last_checked directly */
    ensure_primes_up_to(temp);
    for (size_t i = 0; i < primes_cnt; ++i) {
        uint64_t prime = primes[i];
        if (prime > temp / prime) break;
        if (temp % prime == 0) {
            int cnt_exp = 0;
            do {
                temp /= prime;
                ++cnt_exp;
            } while (temp % prime == 0);
            p[(*cnt)++] = prime;
            e[(*cnt - 1)] = cnt_exp;
        }
    }
    if (temp > 1) {
        /* temp is a prime larger than any in the list */
        p[(*cnt)++] = temp;
        e[(*cnt - 1)] = 1;
    }
}

/* ---------- divisor enumeration with digit mask ---------- */
static void gen_divs_rec(size_t idx,
                         uint64_t current,
                         const uint64_t *pr,
                         const int *exp,
                         size_t sz,
                         uint32_t *mask,
                         bool *ok) {
    if (!*ok) return;
    if (idx == sz) {
        /* process divisor 'current' */
        uint64_t val = current;
        while (val) {
            uint8_t d = (uint8_t)(val % 10);
            *mask |= (1u << d);
            if (__builtin_popcount(*mask) > 8) {
                *ok = false;
                return;
            }
            val /= 10;
        }
        if (current == 0) { /* divisor 0 never occurs */
            *ok = false;
        }
        return;
    }
    uint64_t prod = 1;
    for (int e = 0; e <= exp[idx]; ++e) {
        gen_divs_rec(idx + 1, current * prod, pr, exp, sz, mask, ok);
        if (!*ok) return;
        prod *= pr[idx];
    }
}

/* ---------- test if a number's divisor list contains 8 distinct digits ---------- */
static bool has_8_distinct_digits(uint64_t n) {
    uint64_t p[64];
    int e[64];
    size_t cnt;
    factor_uint64(n, p, e, &cnt);
    uint32_t mask = 0;
    bool ok = true;
    gen_divs_rec(0, 1, p, e, cnt, &mask, &ok);
    return ok && (__builtin_popcount(mask) == 8);
}

/* ---------- memoised sequence storage ---------- */
static seq_t *seq_cache = NULL;
static size_t cache_len = 0, cache_cap = 0;
static uint64_t next_candidate = 2;   /* 1 is not a term */

/* Grow the cache array if needed. */
static void grow_cache(void) {
    if (cache_len == cache_cap) {
        cache_cap = cache_cap ? cache_cap * 2 : 16;
        seq_cache = (seq_t *)realloc(seq_cache, cache_cap * sizeof(seq_t));
    }
}

/* ---------- the sequence accessor ---------- */
seq_t a(idx_t n) {
    if (n == 0) return 0;            /* undefined for n < 1, safe */
    while (cache_len < (size_t)n) {
        if (has_8_distinct_digits(next_candidate)) {
            grow_cache();
            seq_cache[cache_len++] = (seq_t)next_candidate;
        }
        ++next_candidate;
    }
    return seq_cache[n - 1];
}
